from collections import deque
def comps(g):
    seen=[[False]*len(g[0]) for _ in g]; res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=0 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; c=[]
                while q:
                    a,b=q.popleft(); c.append((a,b,g[a][b]))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni,nj=a+di,b+dj
                        if 0<=ni<len(g) and 0<=nj<len(g[0]) and g[ni][nj]!=0 and not seen[ni][nj]:
                            seen[ni][nj]=True; q.append((ni,nj))
                res.append(c)
    return res
