# All orientation variants of b matching out shape (10x9): transpose + flips
def orient(A):
    h,w=len(A),len(A[0])
    yield 'id',A
    yield 'T',[A[j][i] for j in range(h) for i in range(w)]
    yield 'FV',[r[::-1] for r in A]           # vertical flip
    yield 'FLH',[list(r)[::-1] for r in A[::-1]]
    yield 'FCW',[[A[h-1-j][i] for j in range(h)] for i in range(w)]   # clockwise rot
    yield 'FWC',[[A[i][w-1-j] for i in range(h)] for j in range(w)]   # counter-clockwise rot
def best(b,O):
    res=[]
    for key,A in orient(b):
        ha,wa=len(A),len(A[0])
        if (ha,wa)!=(len(O),len(O[0])): continue
        for dy in range(-ha,ha):
            for dx in range(-wa,wa):
                mis=sum(1 for i in range(ha) for j in range(wa)
                        if 0<=i+dy<len(O) and 0<=j+dx<len(O[0]) and A[i][j]!=O[i+dy][j+dx])
                res.append((key,dy,dx,mis))
    res.sort(key=lambda x:(x[3],x[0]))
    return res[:5]
