def comps(I):
    H,W=len(I),len(I[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and (i,j) not in seen:
                q=[(i,j)]; s={(i,j)}; seen.add((i,j))
                while q:
                    a,b=q.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=a+dy,b+dx
                        if 0<=yy<H and 0<=xx<W and I[yy][xx]!=0 and (yy,xx) not in seen:
                            seen.add((yy,xx)); q.append((yy,xx)); s.add((yy,xx))
                res.append(s)
    return res
